    for n, ln in enumerate(lines[i + 1 :], start=i + 2):
        if not ln.strip() or ln.startswith("#"):
            continue
        fields = []
        for k, (start, _name) in enumerate(spans):
            end = spans[k + 1][0] if k + 1 < len(spans) else len(ln)
            fields.append(ln[start:end].strip())
        rows.append(fields)
