    name: str
    category: str
    aliases: tuple[str, ...]


@dataclass(frozen=True)
class Suggestion:
    entry_id: str
    description: str
    merchant: str | None
    category: str | None
    reason: str


def clean_description(text: str) -> str:
    """Lower-case text with references, card numbers and frequency words removed."""
    s = _REFERENCE.sub(" ", text)
    s = _CARD.sub(" ", s)
    s = _DIGITS.sub(" ", s)
    s = _FREQUENCY.sub(" ", s)
    s = _SPACE.sub(" ", s).strip().lower()
    return _TRAILING.sub("", s)


