    lines = [
        f"entry     {e.id} on line {e.line} of {statement.source or 'the statement'}",
        f"amount    {format_major(e.minor, statement.currency)} {statement.currency} ({e.minor} minor units)",
        f"date      {e.date.isoformat()}",
